"""Generates the thaw scripts that restore a frozen folder."""

from __future__ import annotations

import os
import time
from pathlib import Path

from . import __version__

# Tokens @@NAME@@ are replaced with single-quoted shell literals.
_SHELL_TEMPLATE = r"""#!/usr/bin/env bash
# ------------------------------------------------------------------
# gitfreeze thaw — restores this folder from its git remote.
# Generated by gitfreeze @@VER@@ on @@CREATED@@.
#
#   ./thaw.sh                 restore the latest of GF_BRANCH
#   ./thaw.sh --at <sha>      restore one exact commit
#
# Needs nothing but git. Safe to re-run. Existing files are kept;
# incoming copies of colliding paths are saved as *.gitfreeze-new.
# ------------------------------------------------------------------
set -u

GF_REMOTE=@@REMOTE@@
GF_REMOTE_FALLBACK=@@FALLBACK@@
GF_BRANCH=@@BRANCH@@
GF_SHA=@@SHA@@

say()  { printf '%s\n' "$*"; }
warn() { printf '%s\n' "$*" >&2; }
die()  { printf 'thaw: %s\n' "$*" >&2; exit 1; }

AT_SHA=""
while [ $# -gt 0 ]; do
  case "$1" in
    --at)  AT_SHA="${2:-}"; [ -n "$AT_SHA" ] || die "--at needs a commit sha"; shift 2 ;;
    -h|--help) say "usage: $0 [--at <sha>]"; exit 0 ;;
    *) die "unknown argument: $1 (supported: --at <sha>)" ;;
  esac
done

command -v git >/dev/null 2>&1 || die "git is required: https://git-scm.com/downloads"
cd "$(dirname "$0")" || die "cannot enter the script's directory"
DEST="$(pwd -P)"

say "thaw: restoring around $GF_BRANCH from $GF_REMOTE"

mkdir -p "$DEST/.gitfreeze" 2>/dev/null || true
TMP="$DEST/.gitfreeze/tmp.thaw.$$"
rm -rf "$TMP" 2>/dev/null || true
mkdir -p "$TMP" || die "cannot create a temp directory under .gitfreeze/"

exclude_local() {
  gd="$(git -C "$DEST" rev-parse --git-dir 2>/dev/null)" || return 0
  case "$gd" in
    /*|[A-Za-z]:[\\/]*) ;;
    *) gd="$DEST/$gd" ;;
  esac
  ex="$gd/info/exclude"
  mkdir -p "$(dirname "$ex")" 2>/dev/null || true
  for pat in '.gitfreeze/' '.gitfreeze.toml' 'thaw.sh' 'thaw.command' 'thaw.cmd'; do
    grep -qxF "$pat" "$ex" 2>/dev/null || printf '%s\n' "$pat" >> "$ex"
  done
}

SRC="$TMP/src"
TARGET="$GF_BRANCH"
[ -n "$AT_SHA" ] && TARGET="$AT_SHA"

if git -C "$DEST" rev-parse --git-dir >/dev/null 2>&1; then
  say "thaw: local git repository found — restoring from it"
  git -C "$DEST" fetch --quiet "$GF_REMOTE" "$GF_BRANCH" 2>/dev/null \
    && say "thaw: fetched the latest $GF_BRANCH" \
    || warn "thaw: fetch not possible (offline or no access) — using local objects"
  git -C "$DEST" worktree add --detach --force "$SRC" "$TARGET" >/dev/null 2>&1 \
    || git -C "$DEST" worktree add --detach --force "$SRC" "$GF_SHA" >/dev/null 2>&1 \
    || die "cannot check out $TARGET (is the commit present in this repository?)"
  FROM_LOCAL=1
else
  say "thaw: no local repository — cloning into a temp directory"
  FROM_LOCAL=0
  if [ -n "$AT_SHA" ]; then
    git clone --quiet "$GF_REMOTE" "$SRC" 2>"$TMP/clone.err" \
      && git -C "$SRC" checkout --quiet "$AT_SHA" 2>/dev/null \
      || rm -rf "$SRC"
  else
    git clone --quiet --branch "$GF_BRANCH" "$GF_REMOTE" "$SRC" 2>"$TMP/clone.err" || rm -rf "$SRC"
  fi
  if [ ! -d "$SRC/.git" ] && [ -n "$GF_REMOTE_FALLBACK" ]; then
    say "thaw: retrying with fallback URL $GF_REMOTE_FALLBACK"
    if [ -n "$AT_SHA" ]; then
      git clone --quiet "$GF_REMOTE_FALLBACK" "$SRC" 2>"$TMP/clone.err" \
        && git -C "$SRC" checkout --quiet "$AT_SHA" 2>/dev/null \
        || rm -rf "$SRC"
    else
      git clone --quiet --branch "$GF_BRANCH" "$GF_REMOTE_FALLBACK" "$SRC" 2>"$TMP/clone.err" || rm -rf "$SRC"
    fi
  fi
  if [ ! -d "$SRC/.git" ]; then
    [ -f "$TMP/clone.err" ] && sed -n '1,30p' "$TMP/clone.err" >&2
    die "clone failed — check your access to $GF_REMOTE (ssh key / token / network)"
  fi
fi

say "thaw: merging files into $DEST (existing files win)"
cd "$SRC" || die "cannot enter the temporary checkout"
while IFS= read -r -d '' f; do
  rel="${f#./}"
  if [ -e "$DEST/$rel" ] || [ -L "$DEST/$rel" ]; then
    if cmp -s "$f" "$DEST/$rel"; then
      : # already identical — nothing to do
    elif cp -p "$f" "$DEST/$rel.gitfreeze-new" 2>/dev/null || cp "$f" "$DEST/$rel.gitfreeze-new"; then
      say "  kept local  $rel  (incoming copy saved as $rel.gitfreeze-new)"
    else
      die "cannot save incoming copy of $rel"
    fi
  else
    mkdir -p "$DEST/$(dirname "$rel")" || die "cannot create a directory for $rel"
    mv "$f" "$DEST/$rel" || die "cannot move $rel"
  fi
done < <(find . -path ./.git -prune -o -type f -print0)

cd "$DEST" || die "cannot return to $DEST"

if [ "$FROM_LOCAL" = "1" ]; then
  git -C "$DEST" worktree remove --force "$SRC" >/dev/null 2>&1 \
    || { rm -rf "$SRC"; git -C "$DEST" worktree prune >/dev/null 2>&1 || true; }
else
  if [ -d "$DEST/.git" ]; then
    mv "$DEST/.git" "$DEST/.git.old.$$" && warn "thaw: moved an unusable .git aside to .git.old.$$"
  fi
  if mv "$SRC/.git" "$DEST/.git" 2>/dev/null; then
    say "thaw: .git put in place — this folder is a normal repository again"
  else
    warn "thaw: could not move .git into place — files were restored without a repository"
  fi
fi
rm -rf "$TMP" 2>/dev/null || true
exclude_local

say ""
say "thaw: done — $GF_BRANCH restored into $DEST"
say "  existing files were left as they were; differing incoming copies end in *.gitfreeze-new"
say "  if the folder was already complete, re-running thaw changes nothing"
say "  you can delete thaw.sh / thaw.command / thaw.cmd now (or keep them)"
"""

_COMMAND_SHIM = """#!/bin/sh
# macOS double-click launcher for thaw.sh
DIR="$(cd "$(dirname "$0")" && pwd)"
exec "$DIR/thaw.sh" "$@"
"""

_CMD_SHIM = """@echo off
rem gitfreeze thaw launcher for Windows (needs Git for Windows)
setlocal
set "GITEXE="
for /f "delims=" %%G in ('where git 2^>nul') do (
  if not defined GITEXE set "GITEXE=%%~fG"
)
if not defined GITEXE (
  echo [thaw] Git not found. Install Git for Windows: https://git-scm.com/downloads
  pause
  exit /b 1
)
set "BASH=%GITEXE%\\..\\..\\bin\\bash.exe"
if not exist "%BASH%" set "BASH=%GITEXE%\\..\\bin\\bash.exe"
if not exist "%BASH%" (
  echo [thaw] Could not find bash.exe next to git at "%GITEXE%".
  pause
  exit /b 1
)
"%BASH%" "%~dp0thaw.sh" %*
set "RC=%ERRORLEVEL%"
if not "%RC%"=="0" (
  echo [thaw] finished with exit code %RC%.
  pause
)
exit /b %RC%
"""


def _shq(value: str) -> str:
    return "'" + str(value).replace("'", "'\\''") + "'"


def _fallback_url(remote_url: str) -> str:
    url = remote_url.strip()
    if url.startswith("git@"):
        host, _, path = url[4:].partition(":")
        if host and path:
            return f"https://{host}/{path}"
    return ""


def write_thaw_scripts(root, meta: dict) -> list[Path]:
    root = Path(root)
    created = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(meta.get("created", time.time())))
    script = _SHELL_TEMPLATE
    replacements = {
        "@@VER@@": __version__,
        "@@CREATED@@": created,
        "@@REMOTE@@": _shq(meta["remote_url"]),
        "@@FALLBACK@@": _shq(_fallback_url(meta["remote_url"])),
        "@@BRANCH@@": _shq(meta["branch"]),
        "@@SHA@@": _shq(meta["sha"]),
    }
    for token, value in replacements.items():
        script = script.replace(token, value)

    sh = root / "thaw.sh"
    command = root / "thaw.command"
    cmd = root / "thaw.cmd"
    sh.write_text(script, encoding="utf-8", newline="\n")
    command.write_text(_COMMAND_SHIM, encoding="utf-8", newline="\n")
    cmd.write_text(_CMD_SHIM, encoding="utf-8", newline="\r\n")
    if os.name != "nt":
        for path in (sh, command):
            try:
                path.chmod(path.stat().st_mode | 0o755)
            except OSError:
                pass
    return [sh, command, cmd]
